<script setup lang="ts">
const supabase=useSupabaseClient();const rows=ref<any[]>([]);const switches=ref<any[]>([]);const show=ref(false);const editId=ref<string|null>(null);const q=ref('');const form=reactive<any>({data_point_code:'',building:'',room:'',wall_position:'',outlet_number:'',patch_panel:'',patch_panel_port:'',switch_id:'',switch_port:'',device:'',status:'Active',tested:false,date_tested:'',technician:'',notes:''})
async function load(){const [{data:r},{data:s}]=await Promise.all([supabase.from('data_points').select('*, switches(switch_code)').order('building').order('data_point_code'),supabase.from('switches').select('id,switch_code,name').order('switch_code')]);rows.value=r||[];switches.value=s||[]}
function add(){editId.value=null;Object.assign(form,{data_point_code:'',building:'',room:'',wall_position:'',outlet_number:'',patch_panel:'',patch_panel_port:'',switch_id:'',switch_port:'',device:'',status:'Active',tested:false,date_tested:'',technician:'',notes:''});show.value=true}function edit(r:any){editId.value=r.id;Object.assign(form,r,{switch_id:r.switch_id||'',date_tested:r.date_tested||''});show.value=true}
async function save(){const payload={...form,switch_id:form.switch_id||null,date_tested:form.date_tested||null};editId.value?await supabase.from('data_points').update(payload).eq('id',editId.value):await supabase.from('data_points').insert(payload);show.value=false;await load()}async function del(r:any){if(confirm(`Delete ${r.data_point_code}?`)){await supabase.from('data_points').delete().eq('id',r.id);await load()}}
const filtered=computed(()=>rows.value.filter(r=>JSON.stringify(r).toLowerCase().includes(q.value.toLowerCase())));onMounted(load)
</script><template><section><div class="pagehead"><div><h2>Data Point Register</h2><p>Trace wall outlets through patch panels to switch ports.</p></div><button class="btn" @click="add">+ Add Data Point</button></div><input v-model="q" class="search" placeholder="Search data points, rooms, patch panels…"><div class="tablewrap"><table><thead><tr><th>Data Point</th><th>Location</th><th>Patch Panel</th><th>Switch / Port</th><th>Device</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="r in filtered" :key="r.id"><td><strong>{{r.data_point_code}}</strong><br><small>{{r.outlet_number}}</small></td><td>{{r.building}}<br><small>{{r.room}} {{r.wall_position}}</small></td><td>{{r.patch_panel||'—'}} / {{r.patch_panel_port||'—'}}</td><td>{{r.switches?.switch_code||'—'}} / {{r.switch_port||'—'}}</td><td>{{r.device||'—'}}</td><td>{{r.status}}</td><td class="nowrap"><button class="link" @click="edit(r)">Edit</button> <button class="link danger" @click="del(r)">Delete</button></td></tr></tbody></table></div><AppModal v-if="show" title="Data Point" @close="show=false"><form class="formgrid" @submit.prevent="save"><label>Data Point ID<input v-model="form.data_point_code" required></label><label>Outlet Number<input v-model="form.outlet_number"></label><label>Building<input v-model="form.building"></label><label>Room<input v-model="form.room"></label><label>Wall Position<input v-model="form.wall_position"></label><label>Patch Panel<input v-model="form.patch_panel"></label><label>Patch Panel Port<input v-model="form.patch_panel_port"></label><label>Switch<select v-model="form.switch_id"><option value="">None</option><option v-for="s in switches" :value="s.id">{{s.switch_code}} — {{s.name}}</option></select></label><label>Switch Port<input v-model="form.switch_port"></label><label>Device<input v-model="form.device"></label><label>Status<select v-model="form.status"><option>Active</option><option>Unused</option><option>Fault</option></select></label><label><input v-model="form.tested" type="checkbox"> Tested</label><label>Date Tested<input v-model="form.date_tested" type="date"></label><label>Technician<input v-model="form.technician"></label><label class="full">Notes<textarea v-model="form.notes"></textarea></label><div class="full right"><button type="button" class="btn secondary" @click="show=false">Cancel</button> <button class="btn">Save</button></div></form></AppModal></section></template>
